-- ClickHouse log store (LOG_STORE=clickhouse) — log entries only.
-- Clients, retention policies and the retention log stay in the control plane (STORAGE_TYPE).
--
-- Apply with Tools/clickhouse-migration.sh (see docs/clickhouse.md). ClickHouse has no
-- transactions: every statement in these files must be safe to run twice (IF NOT EXISTS).
--
-- Columns mirror MariaDB's log_entries after migrations 001–011 and LogEntry::toArray().
-- Timestamps are always UTC.

CREATE TABLE IF NOT EXISTS log_entries
(
    -- ULID (26 chars), generated by the server
    id               String,
    -- Client-supplied correlation ID
    trace_id         String,
    batch_id         Nullable(String),

    app_key          LowCardinality(String),
    -- Deployment / instance, e.g. "vinhedo5"
    app_id           LowCardinality(String),
    user_agent       Nullable(String),
    -- Client IP as seen by the server (005)
    sender_ip        Nullable(String),
    -- tcp | udp; null for server-generated or legacy entries (009)
    transport        LowCardinality(Nullable(String)),

    level            Enum8('debug' = 1, 'info' = 2, 'notice' = 3, 'warning' = 4, 'error' = 5, 'critical' = 6),
    category         LowCardinality(String) DEFAULT 'general',
    message          String CODEC(ZSTD(3)),
    -- e.g. "Card declined for order {orderId}" (007)
    message_template Nullable(String) CODEC(ZSTD(3)),
    -- Raw JSON object, read with JSONExtract* at query time. Revisit the native JSON type
    -- once LogStream has run on the pinned version for a while.
    context          Nullable(String) CODEC(ZSTD(3)),

    -- When the event happened (microseconds)
    timestamp        DateTime64(6, 'UTC') CODEC(Delta, ZSTD(1)),
    -- When the server stored it; also the ReplacingMergeTree version (a retried batch wins)
    created_at       DateTime64(6, 'UTC') DEFAULT now64(6),

    -- Point lookups: GET /api/logs/:id accepts an id or a trace_id
    INDEX idx_id               id               TYPE bloom_filter(0.01) GRANULARITY 4,
    INDEX idx_trace_id         trace_id         TYPE bloom_filter(0.01) GRANULARITY 4,
    INDEX idx_batch_id         batch_id         TYPE bloom_filter(0.01) GRANULARITY 4,
    INDEX idx_message_template message_template TYPE bloom_filter(0.01) GRANULARITY 4,
    -- search= is a case-insensitive substring match: n-grams of lower(message)
    INDEX idx_message          lower(message)   TYPE ngrambf_v1(3, 65536, 3, 0) GRANULARITY 4,
    -- context_search= matches whole words (as MariaDB's FULLTEXT does): tokens of lower(context)
    INDEX idx_context          lower(ifNull(context, '')) TYPE tokenbf_v1(32768, 3, 0) GRANULARITY 4
)
-- Rows with the same sorting key (app_key, timestamp, id) are the same entry written twice
-- (a retried batch); merges keep one. Queries that must be exact can add FINAL.
ENGINE = ReplacingMergeTree(created_at)
-- One partition per day: "older than N days" retention is a DROP PARTITION.
PARTITION BY toYYYYMMDD(timestamp)
ORDER BY (app_key, timestamp, id)
-- Backstop only: retention policies normally delete much earlier (7 days today, 1 month at most).
TTL toDateTime(timestamp) + INTERVAL 35 DAY DELETE
SETTINGS ttl_only_drop_parts = 1;
